additionalCss:
:root,
[data-theme="light"],
[data-theme="dark"] {
    --sui-bg-primary:   var(--sg-bg);
    --sui-bg-secondary: var(--sg-bg-subtle);
    --sui-bg-tertiary:  var(--sg-bg-muted);
    --sui-text-primary:   var(--sg-fg);
    --sui-text-secondary: var(--sg-fg-subtle);
    --sui-text-muted:     var(--sg-fg-muted);
    --sui-text-disabled:  var(--sg-fg-disabled);
    --sui-border:       var(--sg-border);
    --sui-divider:      var(--sg-divider);
    --sui-border-hover: var(--sg-border-strong);
    --sui-border-focus: var(--sg-border-focus);
    --sui-accent:        var(--sg-color-primary);
    --sui-primary:       var(--sg-color-primary);
    --sui-accent-hover:  var(--sg-color-primary-hover);
    --sui-accent-active: var(--sg-color-primary-active);
    --sui-success:        var(--sg-color-success);
    --sui-success-bg:     var(--sg-color-success-subtle);
    --sui-danger:        var(--sg-color-danger);
    --sui-danger-bg:     var(--sg-color-danger-subtle);
    --sui-warn:        var(--sg-color-warning);
    --sui-warn-bg:     var(--sg-color-warning-subtle);
    --sui-info:        var(--sg-color-info);
    --sui-info-bg:     var(--sg-color-info-subtle);
    --sui-shadow-sm: var(--sg-shadow-sm);
    --sui-shadow-md: var(--sg-shadow-md);
    --sui-shadow-lg: var(--sg-shadow-lg);
    --sui-overlay-bg: var(--sg-bg-overlay);
    --sui-glass-bg:     var(--sg-bg-glass);
    --sui-glass-border: var(--sg-border-glass);
    --sui-glass-blur:   var(--sg-blur-glass);
    --sui-hover-bg:    rgba(30, 58, 138, 0.06);
    --sui-active-bg:   rgba(30, 58, 138, 0.10);
    --sui-selected-bg: var(--sg-color-primary-muted);
    --sui-font-family:    var(--sg-font);
    --sui-font-size-xs:   var(--sg-text-xs);
    --sui-font-size-sm:   var(--sg-text-sm);
    --sui-font-size-base: var(--sg-text-base);
    --sui-font-size-lg:   var(--sg-text-lg);
    --sui-radius-sm:   var(--sg-radius-sm);
    --sui-radius-md:   var(--sg-radius-md);
    --sui-radius-lg:   var(--sg-radius-lg);
    --sui-radius-full: var(--sg-radius-full);
}

/* ── Glass Tinted — Card ── */
[data-theme-id="glass-tinted"] .sgc-card {
    background: oklch(0.92 0.08 220 / 0.55);
    backdrop-filter: blur(16px) saturate(160%);
    -webkit-backdrop-filter: blur(16px) saturate(160%);
    border: 1px solid oklch(0.8 0.1 220 / 0.3);
    border-radius: 14px;
    box-shadow:
        0 4px 16px oklch(0.5 0.1 220 / 0.1),
        inset 0 1px 0 oklch(1 0.05 220 / 0.4);
    transition: border-color 250ms ease,
                box-shadow   250ms ease;
}
[data-theme-id="glass-tinted"] .sgc-card:hover {
    border-color: oklch(0.7 0.12 220 / 0.45);
    box-shadow:
        0 8px 24px oklch(0.5 0.1 220 / 0.15),
        inset 0 1px 0 oklch(1 0.05 220 / 0.5);
}

/* ── Glass Tinted — Surface ── */
[data-theme-id="glass-tinted"] .sgc-surface {
    background: oklch(0.94 0.06 220 / 0.5);
    backdrop-filter: blur(14px) saturate(150%);
    -webkit-backdrop-filter: blur(14px) saturate(150%);
    border: 1px solid oklch(0.8 0.08 220 / 0.25);
    border-radius: 12px;
}

/* ── Glass Tinted — Buttons ── */
[data-theme-id="glass-tinted"] .sgc-btn {
    border-radius: 10px;
    font-weight: 500;
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid oklch(0.8 0.08 220 / 0.25);
    box-shadow: 0 2px 8px oklch(0.5 0.1 220 / 0.08);
    transition: background-color 200ms ease,
                border-color     200ms ease,
                box-shadow       200ms ease,
                transform        100ms ease;
}
[data-theme-id="glass-tinted"] .sgc-btn:hover {
    box-shadow: 0 4px 16px oklch(0.5 0.1 220 / 0.15);
    transform: translateY(-1px);
}
[data-theme-id="glass-tinted"] .sgc-btn.sgc-btn-primary {
    background: oklch(0.50 0.18 220);
    border: 1px solid oklch(0.45 0.18 220);
    color: oklch(1 0 0);
    box-shadow: 0 2px 12px oklch(0.50 0.18 220 / 0.3);
}
[data-theme-id="glass-tinted"] .sgc-btn.sgc-btn-primary:hover:not(:disabled) {
    background: oklch(0.45 0.18 220);
    border-color: oklch(0.40 0.18 220);
    box-shadow: 0 4px 20px oklch(0.50 0.18 220 / 0.4);
}
[data-theme-id="glass-tinted"] .sgc-btn.sgc-btn-ghost {
    background: oklch(0.92 0.06 220 / 0.4);
    border: 1px solid oklch(0.8 0.08 220 / 0.2);
}
[data-theme-id="glass-tinted"] .sgc-btn.sgc-btn-ghost:hover {
    background: oklch(0.90 0.08 220 / 0.5);
}
[data-theme-id="glass-tinted"] .sgc-btn:focus-visible {
    outline: none;
    box-shadow: 0 0 0 2px oklch(0.96 0.04 220),
                0 0 0 4px oklch(0.50 0.18 220);
}

/* ── Glass Tinted — Inputs ── */
[data-theme-id="glass-tinted"] .sgc-input,
[data-theme-id="glass-tinted"] .sgc-select,
[data-theme-id="glass-tinted"] .sgc-textarea {
    background: oklch(0.95 0.04 220 / 0.5);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    border: 1px solid oklch(0.8 0.08 220 / 0.25);
    border-radius: 10px;
    color: oklch(0.14 0.02 220);
    transition: border-color 200ms ease,
                box-shadow   200ms ease;
}
[data-theme-id="glass-tinted"] .sgc-input:focus,
[data-theme-id="glass-tinted"] .sgc-select:focus,
[data-theme-id="glass-tinted"] .sgc-textarea:focus {
    border-color: oklch(0.50 0.18 220);
    box-shadow: 0 0 0 2px oklch(0.50 0.18 220 / 0.15);
    background: oklch(0.97 0.03 220 / 0.6);
    outline: none;
}

/* ── Glass Tinted — Nav ── */
[data-theme-id="glass-tinted"] .sgc-nav {
    background: oklch(0.90 0.06 220 / 0.5);
    backdrop-filter: blur(20px) saturate(160%);
    -webkit-backdrop-filter: blur(20px) saturate(160%);
    border: 1px solid oklch(0.8 0.08 220 / 0.2);
}
[data-theme-id="glass-tinted"] .sgc-nav-link {
    border-radius: 8px;
    padding: 6px 12px;
    color: oklch(0.35 0.06 220);
    transition: background 200ms ease,
                color      200ms ease;
}
[data-theme-id="glass-tinted"] .sgc-nav-link:hover {
    background: oklch(0.50 0.15 220 / 0.1);
    color: oklch(0.20 0.08 220);
}
[data-theme-id="glass-tinted"] .sgc-nav-link.active {
    background: oklch(0.50 0.18 220 / 0.15);
    color: oklch(0.45 0.18 220);
}

/* ── Glass Tinted — Modal ── */
[data-theme-id="glass-tinted"] .sgc-modal-content {
    background: oklch(0.92 0.06 220 / 0.6);
    backdrop-filter: blur(24px) saturate(180%);
    -webkit-backdrop-filter: blur(24px) saturate(180%);
    border: 1px solid oklch(0.8 0.1 220 / 0.35);
    border-radius: 16px;
    box-shadow:
        0 16px 48px oklch(0.5 0.1 220 / 0.15),
        inset 0 1px 0 oklch(1 0.05 220 / 0.4);
}

/* ── Glass Tinted — Dropdown ── */
[data-theme-id="glass-tinted"] .sgc-dropdown-menu {
    background: oklch(0.92 0.06 220 / 0.55);
    backdrop-filter: blur(20px) saturate(160%);
    -webkit-backdrop-filter: blur(20px) saturate(160%);
    border: 1px solid oklch(0.8 0.08 220 / 0.25);
    border-radius: 12px;
    box-shadow: 0 8px 24px oklch(0.5 0.1 220 / 0.1);
}

/* ── Glass Tinted — Selection ── */
[data-theme-id="glass-tinted"] ::selection {
    background: oklch(0.50 0.18 220 / 0.2);
    color: oklch(0.14 0.02 220);
}

/* ── Glass Tinted — Progress ── */
[data-theme-id="glass-tinted"] .sgc-progress-fill {
    background: linear-gradient(90deg, oklch(0.50 0.18 220), oklch(0.55 0.16 240));
    border-radius: 9999px;
}

/* ── Glass Tinted — Scrollbar ── */
[data-theme-id="glass-tinted"] ::-webkit-scrollbar-thumb {
    background: oklch(0.75 0.06 220 / 0.5);
    border-radius: 9999px;
}
[data-theme-id="glass-tinted"] ::-webkit-scrollbar-thumb:hover {
    background: oklch(0.65 0.08 220 / 0.6);
}

/* ── Glass Tinted — Reduced motion ── */
@media (prefers-reduced-motion: reduce) {
    [data-theme-id="glass-tinted"] *,
    [data-theme-id="glass-tinted"] *::before,
    [data-theme-id="glass-tinted"] *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
        scroll-behavior: auto !important;
    }
}
